"""Hosted A-share market data and explicitly experimental native forecasts."""
from __future__ import annotations

import hashlib
import json
import logging
import math
import os
import re
import ssl
import urllib.request
from datetime import datetime, timedelta
from typing import Any
from zoneinfo import ZoneInfo

import certifi
import numpy as np
import pandas as pd
from fastapi import Depends, FastAPI, HTTPException, Request
from src.api.security import require_auth
from starlette.concurrency import run_in_threadpool

_LOG = logging.getLogger(__name__)
_TZ = ZoneInfo("Asia/Shanghai")
_VERSION = "mona-ridge-walkforward-v1"
_FACTORS = ("qlib158_kmid", "qlib158_klen", "qlib158_ma5", "qlib158_ma20",
            "qlib158_roc5", "qlib158_std20", "qlib158_vma5")


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _now() -> datetime:
    return datetime.now(_TZ)


def _number(value: Any) -> float:
    number = float(value)
    if not math.isfinite(number):
        raise ValueError("non-finite market value")
    return number


def _source_days(symbol: str) -> tuple[list[dict], dict]:
    # User input is a validated identifier, never a URL; redirects are refused.
    code, exchange = symbol.split(".")
    token = exchange.lower() + code
    url = "https://web.ifzq.gtimg.cn/appstock/app/day/query?code=" + token
    opener = urllib.request.build_opener(
        _NoRedirect(), urllib.request.HTTPSHandler(context=ssl.create_default_context(cafile=certifi.where()))
    )
    request = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0", "Referer": "https://gu.qq.com/"})
    with opener.open(request, timeout=18) as response:
        raw = response.read(2_000_001)
    if len(raw) > 2_000_000:
        raise ValueError("market response too large")
    payload = json.loads(raw)
    if payload.get("code") != 0:
        raise ValueError("market source rejected query")
    stock = payload["data"][token]
    quote = stock["qt"][token]
    as_of = datetime.strptime(quote[30], "%Y%m%d%H%M%S").replace(tzinfo=_TZ).isoformat()
    price, previous = _number(quote[3]), _number(quote[4])
    if min(price, previous) <= 0:
        raise ValueError("quote price unavailable")
    return stock["data"], {
        "price": price, "previous_close": previous, "change": price - previous,
        "change_pct": (price / previous - 1) * 100, "name": str(quote[1]), "as_of": as_of,
    }


def _minute_position(time: str) -> int | None:
    minutes = int(time[:2]) * 60 + int(time[2:])
    if 570 <= minutes <= 690:
        return minutes - 570
    if 780 <= minutes <= 900:
        return minutes - 780 + 121
    return None


def _minute_days(days: list[dict], now: datetime) -> pd.DataFrame:
    rows = []
    for day in days:
        date = datetime.strptime(day["date"], "%Y%m%d").date()
        previous_volume, previous_amount = 0.0, 0.0
        for raw in day["data"]:
            parts = raw.split()
            position = _minute_position(parts[0])
            if position is None:
                continue  # Tencent also includes post-market fixed-price trades after 15:00.
            stamp = datetime.strptime(day["date"] + parts[0], "%Y%m%d%H%M").replace(tzinfo=_TZ)
            if stamp > now:
                continue
            price, volume, amount = map(_number, parts[1:4])
            if price <= 0 or volume < previous_volume or amount < previous_amount:
                raise ValueError("invalid cumulative intraday data")
            rows.append({"trade_date": stamp, "close": price, "volume": volume - previous_volume,
                         "amount": amount - previous_amount, "day": date.isoformat(), "position": position})
            previous_volume, previous_amount = volume, amount
    if not rows:
        return pd.DataFrame()
    return pd.DataFrame(rows).drop_duplicates("trade_date").sort_values("trade_date").reset_index(drop=True)


def _market_state(frame: pd.DataFrame, now: datetime) -> str:
    latest = frame.iloc[-1]["trade_date"]
    if latest.date() != now.date():
        return "closed"
    clock = now.hour * 60 + now.minute
    if 690 < clock < 780:
        return "recess"
    if 570 <= clock <= 900:
        return "open" if (now - latest).total_seconds() <= 300 else "stale"
    return "closed"


def _minute_target(latest: datetime, horizon: int, position: int) -> datetime:
    target = position + horizon
    clock = 570 + target if target <= 120 else 780 + target - 121
    return latest.replace(hour=clock // 60, minute=clock % 60, second=0, microsecond=0)


def _daily_bars(symbol: str, now: datetime, adjusted: bool = False) -> pd.DataFrame:
    from backtest.loaders.tencent_loader import DataLoader

    loader = DataLoader()
    start, end = (now.date() - timedelta(days=1500)).isoformat(), now.date().isoformat()
    if adjusted:
        result = loader.fetch([symbol], start, end, interval="1D").get(symbol)
        if result is not None and result.attrs.get("adjustment") != "split_dividend":
            raise ValueError("adjusted return history unavailable")
    else:
        result = loader._fetch_one(symbol, start, end, forward_adjusted=False)
    if result is None or result.empty:
        return pd.DataFrame()
    result = result[~result.index.duplicated(keep="last")].sort_index()
    return result.loc[result.index.date <= now.date()]


def market_snapshot(symbol: str, interval: str) -> dict:
    now = _now()
    base = {"symbol": symbol, "interval": interval, "bars": [], "quote": None,
            "trading_date": None, "market_open": False, "market_state": "closed",
            "source": "tencent", "observed_at": now.isoformat(), "volume_unit": "lots", "adjustment": "none"}
    if symbol.endswith(".BJ"):
        return {**base, "status": "unavailable", "reason": "当前免费行情源暂不提供该北交所股票。"}
    try:
        days, quote = _source_days(symbol)
        minutes = _minute_days(days, now)
        if minutes.empty:
            raise ValueError("no trading-session points")
        state = _market_state(minutes, now)
        if interval == "intraday":
            date = minutes.iloc[-1]["day"]
            frame = minutes[minutes["day"] == date]
            bars = [{"trade_date": row.trade_date.isoformat(), "close": row.close,
                     "volume": row.volume, "amount": row.amount} for row in frame.itertuples()]
        else:
            frame = _daily_bars(symbol, now)
            if frame.empty:
                raise ValueError("daily history missing")
            date = frame.index[-1].date().isoformat()
            bars = [{"trade_date": stamp.date().isoformat(), **{key: _number(row[key]) for key in
                     ("open", "high", "low", "close", "volume")}} for stamp, row in frame.tail(360).iterrows()]
        if quote["as_of"][:10] != date:
            raise ValueError("quote and series dates do not match")
        return {**base, "status": "ok", "bars": bars, "quote": quote, "trading_date": date,
                "market_open": state == "open", "market_state": state}
    except Exception as exc:
        _LOG.warning("Workbench market unavailable for %s (%s)", symbol, type(exc).__name__)
        return {**base, "status": "unavailable", "reason": "暂时未能读取该股票的行情，请稍后刷新。"}


def _daily_features(frame: pd.DataFrame, symbol: str) -> pd.DataFrame:
    from src.factors.registry import get_default_registry

    panel = {key: frame[[key]].rename(columns={key: symbol}) for key in ("open", "high", "low", "close", "volume")}
    registry = get_default_registry()
    return pd.DataFrame({factor: registry.compute(factor, panel)[symbol] for factor in _FACTORS}, index=frame.index)


def _minute_features(frame: pd.DataFrame) -> pd.DataFrame:
    groups = frame.groupby("day", sort=False)
    result = pd.DataFrame(index=frame.index)
    for lag in (1, 5, 15):
        value = frame["close"] / groups["close"].shift(lag) - 1
        result[f"minute_return_{lag}"] = value.where(frame["position"] - groups["position"].shift(lag) == lag)
    mean_volume = groups["volume"].transform(lambda values: values.rolling(15, min_periods=15).mean())
    result["minute_volume_ratio_15"] = frame["volume"] / mean_volume.replace(0, np.nan)
    result["session_position"] = frame["position"] / 241
    return result


def _training_samples(frame: pd.DataFrame, features: pd.DataFrame, horizon: int, intraday: bool):
    close = frame["close"]
    target = close.shift(-horizon) / close - 1
    valid = features.notna().all(axis=1) & np.isfinite(features).all(axis=1) & target.notna()
    if intraday:
        valid &= frame["day"] == frame["day"].shift(-horizon)
        valid &= frame["position"].shift(-horizon) - frame["position"] == horizon
    positions = np.flatnonzero(valid.to_numpy())
    return positions, features.iloc[positions].to_numpy(), target.iloc[positions].to_numpy()


def _splits(frame: pd.DataFrame, positions: np.ndarray, horizon: int, intraday: bool):
    if intraday:
        # Whole observed days are held out; no label is ever allowed across overnight.
        days = frame.iloc[positions]["day"].to_numpy()
        for day in sorted(set(days))[2:]:
            train, test = np.flatnonzero(days < day), np.flatnonzero(days == day)
            if len(train) >= 150 and len(test) >= 20:
                yield train, test
    else:
        from src.quantlib.crossvalidation import purged_walk_forward_splits

        # Express actual outcome endpoints in sample positions, preserving gaps
        # left by feature warmup or missing observations.
        ends = np.searchsorted(positions, positions + horizon, side="right") - 1
        for split in purged_walk_forward_splits(len(positions), ends, n_folds=4):
            if len(split.train) >= 100:
                yield split.train, split.test


def _estimate(frame: pd.DataFrame, features: pd.DataFrame, horizon: int, intraday: bool):
    from sklearn.linear_model import Ridge
    from sklearn.pipeline import make_pipeline
    from sklearn.preprocessing import StandardScaler

    positions, x, y = _training_samples(frame, features, horizon, intraday)
    if len(x) < (250 if intraday else 240) or not np.isfinite(features.iloc[-1]).all():
        raise ValueError("insufficient training observations")
    residuals, truth, predictions, folds = [], [], [], 0
    for train, test in _splits(frame, positions, horizon, intraday):
        model = make_pipeline(StandardScaler(), Ridge(alpha=20.0))
        model.fit(x[train], y[train])
        predicted = model.predict(x[test])
        residuals.extend((y[test] - predicted).tolist())
        truth.extend(y[test].tolist())
        predictions.extend(predicted.tolist())
        folds += 1
    if len(truth) < 50 or folds < 2:
        raise ValueError("insufficient out-of-sample observations")
    model = make_pipeline(StandardScaler(), Ridge(alpha=20.0))
    model.fit(x, y)
    estimate = float(model.predict(features.iloc[[-1]].to_numpy())[0])
    lo, hi = np.quantile(residuals, [0.1, 0.9])
    mae = float(np.mean(np.abs(np.asarray(truth) - predictions)))
    baseline = float(np.mean(np.abs(truth)))
    return estimate, float(lo), float(hi), {"step": horizon, "mae": mae,
        "baseline_mae": baseline, "samples": len(truth), "folds": folds}, len(x)


def _forecast_base(symbol: str, interval: str) -> dict:
    return {"symbol": symbol, "interval": interval, "status": "unavailable", "experimental": True,
            "as_of": None, "last_price": None, "points": [],
            "horizon_unit": "trading_minute" if interval == "intraday" else "trading_day",
            "model_version": _VERSION, "training_cutoff": None, "training_rows": 0,
            "data_fingerprint": None, "features": [],
            "validation": {"method": "day_walk_forward" if interval == "intraday" else "purged_walk_forward",
                           "mae": None, "baseline_mae": None, "samples": 0, "folds": 0,
                           "beat_baseline": None, "by_horizon": []}}


def forecast_snapshot(symbol: str, interval: str) -> dict:
    base = _forecast_base(symbol, interval)
    if symbol.endswith(".BJ"):
        return {**base, "reason_code": "market_not_supported", "reason": "当前免费行情源暂不提供该北交所股票。"}
    try:
        now = _now()
        days, quote = _source_days(symbol)
        minute_frame = _minute_days(days, now)
        if minute_frame.empty:
            raise ValueError("insufficient market data")
        base["last_price"] = quote["price"]
        if interval == "intraday":
            base["as_of"] = minute_frame.iloc[-1]["trade_date"].isoformat()
            base["last_price"] = float(minute_frame.iloc[-1]["close"])
            if _market_state(minute_frame, now) != "open":
                return {**base, "reason_code": "intraday_market_closed",
                        "reason": "分时预测只在当前交易时段推演剩余分钟；休市或行情未更新时不绘制未来曲线。"}
            frame = minute_frame
            features = _minute_features(frame)
            latest = frame.iloc[-1]
            position = int(latest["position"])
            remaining = 241 - position
            horizons = [step for step in (1, 5, 10, 15, 20, 25, 30)
                        if step <= remaining and _minute_target(latest["trade_date"], step, position) > now]
            if not horizons:
                return {**base, "reason_code": "intraday_no_future_minutes",
                        "reason": "当前行情时点之后已没有可预测的剩余交易分钟。"}
        else:
            frame = _daily_bars(symbol, now, adjusted=True)
            raw = _daily_bars(symbol, now)
            # A partly observed candle is never treated as a completed daily sample.
            if now.hour * 60 + now.minute < 900:
                raw = raw.loc[raw.index.date < now.date()] if not raw.empty else raw
            if raw.empty:
                raise ValueError("insufficient completed daily history")
            cutoff = raw.index[-1].date()
            frame = frame.loc[frame.index.date <= cutoff] if not frame.empty else frame
            if frame.empty or frame.index[-1].date() != cutoff or cutoff.isoformat() > quote["as_of"][:10]:
                return {**base, "reason_code": "daily_close_pending",
                        "reason": "已收盘日K的原始价格与复权历史暂未对齐，请稍后刷新。"}
            if cutoff.isoformat() == quote["as_of"][:10] and not math.isclose(
                float(raw.iloc[-1]["close"]), quote["price"], abs_tol=0.005, rel_tol=0,
            ):
                raise ValueError("completed daily close and quote do not match")
            base["last_price"] = float(raw.iloc[-1]["close"])
            features = _daily_features(frame, symbol)
            base["as_of"] = frame.index[-1].date().isoformat()
            horizons = [1, 2, 3, 4, 5]
        if not horizons:
            raise ValueError("no future trading minutes")
        base.update(training_cutoff=base["as_of"], features=list(features.columns),
                    data_fingerprint=hashlib.sha256(frame.to_csv(index=True).encode()).hexdigest())
        points, evaluations, training_rows = [], [], []
        for horizon in horizons:
            predicted, lo, hi, evaluation, rows = _estimate(frame, features, horizon, interval == "intraday")
            price = base["last_price"]
            # Residual quantiles describe historical OOS errors, not confidence probabilities.
            points.append({"step": horizon, "label": f"+{horizon}" + ("交易分钟" if interval == "intraday" else "交易日"),
                           "price": max(0.01, price * (1 + predicted)),
                           "lower": max(0.01, price * (1 + predicted + lo)),
                           "upper": max(0.01, price * (1 + predicted + hi))})
            if interval == "intraday":
                latest = frame.iloc[-1]
                points[-1]["trade_date"] = _minute_target(
                    latest["trade_date"], horizon, int(latest["position"]),
                ).isoformat()
            evaluations.append(evaluation)
            training_rows.append(rows)
        last = evaluations[-1]
        return {**base, "status": "ok", "points": points, "training_rows": min(training_rows),
                "validation": {**base["validation"], **{key: last[key] for key in ("mae", "baseline_mae", "samples", "folds")},
                               "beat_baseline": last["mae"] < last["baseline_mae"], "by_horizon": evaluations},
                "interval_method": "OOS residual 10/90 empirical range; not calibrated probability",
                "limitations": "单股有限历史实验，不含交易成本；未超过零收益基线时不代表有预测优势。"}
    except Exception as exc:
        _LOG.warning("Workbench forecast unavailable for %s (%s)", symbol, type(exc).__name__)
        return {**base, "reason_code": "forecast_data_insufficient",
                "reason": "可用行情、复权历史或样本外验证数据不足，暂时无法生成预测。"}


def register_mona_workbench_market(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    def validate(request: Request, symbol: str, interval: str):
        query = request.query_params
        if set(query) != {"symbol", "interval"} or any(len(query.getlist(key)) != 1 for key in query):
            raise HTTPException(422, "workbench market query fields do not match the contract")
        if not re.fullmatch(r"\d{6}\.(?:SH|SZ|BJ)", symbol) or interval not in {"intraday", "1D"}:
            raise HTTPException(422, "unsupported symbol or interval")

    @app.get("/mona/workbench-market", dependencies=[Depends(require_auth)])
    async def market(request: Request, symbol: str, interval: str) -> dict:
        validate(request, symbol, interval)
        return await run_in_threadpool(market_snapshot, symbol, interval)

    @app.get("/mona/workbench-forecast", dependencies=[Depends(require_auth)])
    async def forecast(request: Request, symbol: str, interval: str) -> dict:
        validate(request, symbol, interval)
        return await run_in_threadpool(forecast_snapshot, symbol, interval)
